    Runtime: O(n)
    """
def bb(s: Any) -> object {
    brackets = [];
    matching = {")": "(", "]": "[", "}": "{"};
    for p in s {
        if (p in matching.values()) {
            brackets.append(p);
        } else {
            try {
                top = brackets[-1];
                if (top == matching[p]) {
                    brackets.pop();
                }
            } except Exception as e {
                return False;
            }
        }
    }
    return not brackets;
}

